def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The color key is a short nonzero sequence repeated on three identical rows.
    key = None
    key_region = None
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            nz = [c for c, v in enumerate(grid[r]) if v != 0]
            if nz and nz == list(range(nz[0], nz[-1] + 1)):
                vals = grid[r][nz[0]:nz[-1] + 1]
                if len(vals) >= 2:
                    key = vals
                    key_region = (r, r + 3, nz[0], nz[-1] + 1)
                    break
    if key is None:
        return out

    # Find colored connected components outside the key and choose the repeated motif.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            color = grid[r][c]
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not all(key_region[0] <= y < key_region[1] and key_region[2] <= x < key_region[3] for y, x in cells):
                miny = min(y for y, x in cells); maxy = max(y for y, x in cells)
                minx = min(x for y, x in cells); maxx = max(x for y, x in cells)
                mask = frozenset((y-miny, x-minx) for y, x in cells)
                comps.append((color, miny, minx, maxy-miny+1, maxx-minx+1, mask, len(cells)))

    candidates = [obj for obj in comps if obj[0] in key]
    if not candidates:
        return out
    # All copies share a silhouette; use the largest component as the template.
    template = max(candidates, key=lambda obj: obj[6])
    color0, top, left, mh, mw, mask, _ = template

    # Preserve the alignment of an existing motif to its position in the key.
    anchors = [obj for obj in candidates if obj[5] == mask]
    anchor = min(anchors, key=lambda obj: obj[1])
    start_y = anchor[1] - key.index(anchor[0]) * mh

    # Remove the key and all source motif copies, then draw the ordered stack.
    kr0, kr1, kc0, kc1 = key_region
    for y in range(kr0, kr1):
        for x in range(kc0, kc1):
            out[y][x] = 0
    for color, y0, x0, hh, ww, shape, _ in comps:
        if shape == mask:
            for dy, dx in shape:
                out[y0+dy][x0+dx] = 0
    for i, color in enumerate(key):
        y0 = start_y + i * mh
        for dy, dx in mask:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


